package com.mrrwhoo1.multidl

import android.Manifest
import android.content.ActivityNotFoundException
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.platform.LocalContext
import androidx.core.content.ContextCompat
import com.chaquo.python.Python
import com.chaquo.python.android.AndroidPlatform
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class MainActivity : ComponentActivity() {

    // Android 13+ asks permission before an app may show notifications.
    // Without it the background download still works, but its notification is hidden.
    private val notificationPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.RequestPermission()) { }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Draw behind the status/navigation bars on every Android version,
        // so the theme colour covers the whole screen.
        enableEdgeToEdge()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
            != PackageManager.PERMISSION_GRANTED
        ) {
            notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        }

        if (!Python.isStarted()) {
            Python.start(AndroidPlatform(this))
        }

        // The download queue lives here, outside any screen, so it outlives screen rebuilds.
        DownloadCenter.init(applicationContext)

        setContent {
            //======================Update checker
            val context = LocalContext.current
            var updateInfo by remember { mutableStateOf<UpdateInfo?>(null) }

            LaunchedEffect(Unit) {
                val currentVersionCode = context.packageManager
                .getPackageInfo(context.packageName, 0)
                .versionCode

                updateInfo = withContext(Dispatchers.IO) {
                    UpdateChecker.checkForUpdate(currentVersionCode)
                }
            }
            //==================================
            val prefs = remember { getSharedPreferences(PREFS_NAME, MODE_PRIVATE) }
            var themeMode by remember {
                mutableStateOf(
                    when {
                        // A choice made with the new System / Light / Dark selector.
                        prefs.contains(KEY_THEME_MODE) ->
                            ThemeMode.fromSaved(prefs.getString(KEY_THEME_MODE, null))

                        // Someone who used the old dark/light switch keeps what they picked.
                        prefs.contains(KEY_DARK_THEME) ->
                            if (prefs.getBoolean(KEY_DARK_THEME, true)) ThemeMode.DARK else ThemeMode.LIGHT

                        // Brand new install: follow the phone.
                        else -> ThemeMode.SYSTEM
                    }
                )
            }

            // isSystemInDarkTheme() is the phone's current setting, and it updates by itself.
            val isDark = when (themeMode) {
                ThemeMode.LIGHT -> false
                ThemeMode.DARK -> true
                ThemeMode.SYSTEM -> isSystemInDarkTheme()
            }

            MultiDLTheme(isDark = isDark) {
                MultiDLScreen(
                    themeMode = themeMode,
                    onThemeModeChange = { newMode ->
                        themeMode = newMode
                        prefs.edit().putString(KEY_THEME_MODE, newMode.saved).apply()
                    }
                )
                //update pop up AletDialog window

                updateInfo?.let { update ->
                    androidx.compose.material3.AlertDialog(
                        onDismissRequest = {
                            updateInfo = null
                        },
                        title = {
                            androidx.compose.material3.Text(
                                text = "Update available: ${update.versionName}"
                            )
                        },
                        text = {
                            androidx.compose.material3.Text(
                                text = update.releaseNotes.ifBlank {
                                    "A newer version of MultiDL is available."
                                }
                            )
                        },
                        confirmButton = {
                            androidx.compose.material3.TextButton(
                                onClick = {
                                    val intent = Intent(
                                        Intent.ACTION_VIEW,
                                        Uri.parse(update.downloadUrl)
                                    )
                                    try {
                                        context.startActivity(intent)
                                    } catch (_: ActivityNotFoundException) {
                                        Toast.makeText(
                                            context,
                                            "Unable to open the download page.",
                                            Toast.LENGTH_SHORT
                                        ).show()
                                    }
                                    updateInfo = null
                                }
                            ) {
                                androidx.compose.material3.Text("Download")
                            }
                        },
                        dismissButton = {
                            androidx.compose.material3.TextButton(
                                onClick = {
                                    updateInfo = null
                                }
                            ) {
                                androidx.compose.material3.Text("Later")
                            }
                        }
                    )
                }
            }
        }
    }
}
